class Inner { v = 1; inc(): number { this.v++; return this.v; } }
class Outer { inner: Inner = new Inner(); name = "o"; }
async function main(): Promise<void> {
  const o = new Outer();
  const a: any = o;
  console.log(a.inner.v, typeof a.inner.inc);
  console.log(a.inner.inc(), o.inner.v);
}
